// Normaliza el dataset de Apify al schema interno de JobRadar.
// El output de "run-sync-get-dataset-items" es un array de jobs.
// Distintos actors usan distintos nombres de campos => mapping defensivo.

const jobs = [];

for (const item of $input.all()) {
  const d = item.json;

  // soporta: array directo, {items: [...]}, o item singular
  const candidates = Array.isArray(d)
    ? d
    : (Array.isArray(d.items) ? d.items : [d]);

  for (const j of candidates) {
    const link = String(j.link || j.jobUrl || j.url || j.applyUrl || "").trim();
    if (!link) continue; // sin link no sirve para dedup ni para clickear

    const descRaw = String(
      j.descriptionText || j.description || j.descriptionHtml || ""
    );
    const desc = descRaw
      .replace(/<[^>]+>/g, " ")        // limpiar HTML
      .replace(/&nbsp;/g, " ")
      .replace(/\s+/g, " ")
      .trim();

    jobs.push({
      json: {
        fecha_ingesta: new Date().toISOString(),
        titulo: String(j.title || j.positionName || j.jobTitle || "").trim(),
        empresa: String(j.companyName || j.company || j.organization || "").trim(),
        ubicacion: String(j.location || j.jobLocation || j.candidatesLocation || "").trim(),
        link,
        fuente: "apify_linkedin",
        // truncar a 4000 chars: los primeros parrafos son lo que evalua la IA
        descripcion: desc.slice(0, 4000)
      }
    });
  }
}

if (jobs.length === 0) {
  console.log("OK: el dataset de Apify no trajo ofertas con link (el actor falló o no hay novedades)");
}

return jobs;
